      "content": "package io.github.marishasahay.shortener.link;

import com.github.benmanes.caffeine.cache.Cache;
import java.time.Clock;
import org.springframework.stereotype.Component;

/**
 * Resolves short codes to target URLs on the redirect hot path, backed by a Caffeine cache of
 * {@code code -> Link} in front of the database.
 */
@Component
public class LinkResolver {

  private final Cache<String, Link> redirectCache;
  private final LinkRepository repository;
  private final Clock clock;

  /**
   * Creates the resolver.
   *
   * @param redirectCache the bounded redirect cache
   * @param repository link persistence
   * @param clock time source
   */
  public LinkResolver(Cache<String, Link> redirectCache, LinkRepository repository,
      Clock clock) {
    this.redirectCache = redirectCache;
    this.repository = repository;
    this.clock = clock;
  }

  /**
   * Resolves a code to its target URL.
   * If the link is found in the cache but is expired, it is evicted and a LinkExpiredException is thrown.
   * If the link is not in the cache, it is loaded from the repository, checked for expiry, and then cached.
   *
   * @param code the short code
   * @return the target URL
   * @throws LinkNotFoundException if no active link exists for the code
   * @throws LinkExpiredException if the link has expired
   */
  public String resolve(String code) {
    Link link = redirectCache.get(code, this::load);
    if (link.isExpiredAt(clock.instant())) {
      // If a cached link is found to be expired, evict it to prevent future hits
      // and throw LinkExpiredException.
      redirectCache.invalidate(code);
      throw new LinkExpiredException(code);
    }
    return link.targetUrl();
  }

  /**
   * Removes a code from the cache, e.g. after the link was deleted.
   *
   * @param code the short code
   */
  public void evict(String code) {
    redirectCache.invalidate(code);
  }

  /**
   * Loads a Link from the repository. This method is used by the cache's `get` operation
   * when a key is not present. It checks for expiry before returning the link.
   *
   * @param code the short code
   * @return the Link object
   * @throws LinkNotFoundException if no active link exists for the code
   * @throws LinkExpiredException if the link has expired
   */
  private Link load(String code) {
    Link link = repository.findActiveByCode(code)
        .orElseThrow(() -> new LinkNotFoundException(code));
    // Check expiry here before the link is put into the cache.
    // This ensures that expired links are never initially loaded into the cache.
    if (link.isExpiredAt(clock.instant())) {
      throw new LinkExpiredException(code);
    }
    return link;
  }
}
